"""Summarize node sequence journals without changing the node."""
import argparse
from collections import Counter
import json
from pathlib import Path
import re
import stat


def strict_json(raw):
    def reject_constant(value):
        raise ValueError(value)

    return json.loads(raw, parse_constant=reject_constant)


def regular(path):
    try:
        return stat.S_ISREG(path.lstat().st_mode)
    except FileNotFoundError:
        return False


def read_state(node, bad):
    path = node / "state.json"
    try:
        if not stat.S_ISREG(path.lstat().st_mode):
            raise ValueError("state is not a regular file")
        value = strict_json(path.read_bytes())
    except FileNotFoundError:
        return None
    except (OSError, UnicodeError, ValueError):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return None
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return None
    return value["channels"]


def read_records(path, counts, bad):
    parts = path.read_bytes().split(b"\n")
    for number, raw in enumerate(parts[:-1], 1):
        try:
            value = strict_json(raw)
        except (ValueError, UnicodeError):
            why = "bad_json"
        else:
            seq = value.get("seq") if isinstance(value, dict) else None
            if type(seq) is int and seq >= 1:
                counts[seq] += 1
                continue
            why = "no_seq"
        bad.append({"file": path.name, "line": number, "why": why})
    if parts[-1]:
        bad.append({"file": path.name, "line": len(parts), "why": "torn"})


def channel_summary(node, channel, entries, state, bad):
    pattern = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl\Z")
    segments = []
    for path in entries:
        match = pattern.fullmatch(path.name)
        if match and regular(path):
            segments.append((int(match.group(1)), path))
    paths = [path for _, path in sorted(segments)]
    active = node / (channel + ".active.jsonl")
    if regular(active):
        paths.append(active)

    counts = Counter()
    for path in paths:
        read_records(path, counts, bad)
    seqs = sorted(counts)
    first = seqs[0] if seqs else None
    last = seqs[-1] if seqs else None
    result = {
        "count": sum(counts.values()),
        "first": first,
        "last": last,
        "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
        "dup": [seq for seq in seqs if counts[seq] >= 2],
        "next_seq": None,
        "unacked": None,
        "stale_next": None,
    }
    if state is None:
        return result, False
    fields = state.get(channel)
    valid = isinstance(fields, dict) and type(fields.get("next_seq")) is int
    if channel == "must":
        valid = valid and type(fields.get("acked_upto")) is int
    if not valid:
        return result, True
    result["next_seq"] = fields["next_seq"]
    result["stale_next"] = None if last is None else fields["next_seq"] != last + 1
    if channel == "must":
        result["unacked"] = sum(seq > fields["acked_upto"] for seq in seqs)
    return result, False


def summarize(node):
    bad = []
    state = read_state(node, bad)
    entries = list(node.iterdir())
    channels = {}
    state_bad = False
    for channel in ("obs", "must"):
        channels[channel], invalid = channel_summary(node, channel, entries, state, bad)
        state_bad |= invalid
    if state_bad:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only node sequence gap summary")
    parser.add_argument("folder", type=Path)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
